mat2 obtenirMatriceRotation(float angle) {
    return mat2(
        cos(angle), -sin(angle),
        sin(angle),  cos(angle)
    );
}

struct ResultatDistance {
    float distance;
    float idCellule;
};

ResultatDistance carteScene(vec3 positionRayon, vec3 positionBrute, float facteurMorph, float temps) {
    vec3 positionCourante = positionRayon;
    float idCourant = 0.0;

    vec3 axeLePlusProche;
    float projectionMax;
    float indexAxe;

    for (int niveau = 0; niveau < 5; niveau++) {
        projectionMax = -9.0;

        for (int k = 0; k < 4; k++) {
            vec3 axeTest = vec3(
                1 - 2 * (k & 1),
                1 - 2 * (((k + 1) / 2) % 2),
                1 - 2 * (k / 2)
            );

            float projection = dot(positionCourante, axeTest);
            if (projection > projectionMax) {
                projectionMax = projection;
                axeLePlusProche = axeTest;
                indexAxe = float(k);
            }
        }

        positionCourante = positionCourante * 2.0 - axeLePlusProche * (1.0 - facteurMorph);
        idCourant = idCourant * 4.0 + indexAxe;
    }

    float largeurBoite = 0.05 + 0.02 * sin(temps * 2.0 + idCourant);
    vec3 decalageBoite = abs(positionCourante) - largeurBoite;

    float distanceBoite = length(max(decalageBoite, 0.0)) + min(max(decalageBoite.x, max(decalageBoite.y, decalageBoite.z)), 0.0);
    float distanceSphere = length(positionCourante) - largeurBoite;

    float distanceFormeMelangee = mix(distanceBoite, distanceSphere, facteurMorph) / 32.0;
    float distanceSphereEnglobante = length(positionBrute) - 1.0;

    float distanceFinale = mix(distanceFormeMelangee, distanceSphereEnglobante, facteurMorph * 0.5);

    return ResultatDistance(distanceFinale, idCourant);
}

void mainImage(out vec4 couleurFragment, vec2 coordFragment) {
    vec3 resolution = iResolution;
    float temps = iTime;

    vec2 uvNormalisees = (coordFragment * 2.0 - resolution.xy) / resolution.y;
    vec3 directionRayon = normalize(vec3(uvNormalisees, 2.0));

    float facteurMorph = (1.0 - cos(temps * 0.6)) * 0.415;

    vec3 origineRayon = vec3(0.0, 0.0, -2.6);
    float distanceRayon = 0.0;
    float luminescenceAccumulee = 0.0;
    float idCelluleTouchee = 0.0;
    float distanceCourante = 0.0;

    for (int etape = 0; etape < 96; etape++) {
        if (distanceRayon >= 8.0) break;

        vec3 position = origineRayon + directionRayon * distanceRayon;

        position.xz *= obtenirMatriceRotation(temps * 0.2);
        position.xy *= obtenirMatriceRotation(temps * 0.12);

        float angleTorsion = log(length(position.xz) + 1e-5) * facteurMorph * 1.5;
        position.xz *= obtenirMatriceRotation(angleTorsion);

        vec3 positionBrute = position;
        position = mix(position, normalize(position) * 1.2, facteurMorph);

        ResultatDistance donneesScene = carteScene(position, positionBrute, facteurMorph, temps);
        distanceCourante = donneesScene.distance;

        if (distanceCourante < 0.001) {
            idCelluleTouchee = donneesScene.idCellule;
            break;
        }

        luminescenceAccumulee += 0.0005 / (distanceCourante * distanceCourante + 1e-4);
        distanceRayon += distanceCourante * 0.5;
    }

    vec3 paletteBase = fract(sin(idCelluleTouchee + vec3(0.0, 1.3, 2.7)) * 43758.55);

    float eclairageDirect = (distanceCourante < 0.001) ? (1.0 - distanceRayon * 0.25) : 0.0;
    float intensiteFinale = luminescenceAccumulee * 0.08 + eclairageDirect;

    couleurFragment = vec4(paletteBase * intensiteFinale, 1.0);
}
